# scripts/eval_run_01.py
# Post-training evaluation for run_01: EMA validation loss and 4 conditional
# samples generated by Euler integration of the flow-matching ODE.
import json
import sys
from pathlib import Path

import numpy as np
import torch
import yaml
from torch.utils.data import DataLoader, Subset

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from forge.data.dataset import ForgeSplitDataset  # noqa: E402
from forge.models.dit import DiT  # noqa: E402
from forge.train.flow_matching import FlowMatchingLoss, _validate  # noqa: E402

FM_STEPS = 20
N_SAMPLES = 4


@torch.no_grad()
def sample(model, sdf, scalars, n_steps):
    """Euler integration of dx/dt = v(x_t, t) from t=0 (noise) to t=1."""
    x = torch.randn(sdf.shape[0], 1, sdf.shape[2], sdf.shape[3], device=sdf.device)
    dt = 1.0 / n_steps
    for i in range(n_steps):
        t = torch.full((x.shape[0],), i * dt, device=x.device)
        x = x + model(torch.cat([x, sdf], dim=1), t, scalars) * dt
    return x


def main():
    config = yaml.safe_load((ROOT / "configs/run_01.yaml").read_text(encoding="utf-8"))
    dcfg, pcfg = config["data"], config["paths"]
    device = torch.device("cuda")

    ckpt = torch.load(ROOT / pcfg["checkpoint_dir"] / "final.pt",
                      map_location=device, weights_only=False)
    print(f"checkpoint step: {ckpt['step']}")

    model = DiT(**config["model"]).to(device)
    # AveragedModel wraps the net, so its keys carry a module. prefix
    ema_state = {k[len("module."):]: v for k, v in ckpt["ema"].items()
                 if k.startswith("module.")}
    if not ema_state:
        raise RuntimeError("checkpoint contains no EMA model parameters")
    # strict: a partial load would leave randomly initialised weights in place
    # and publish validation metrics and samples produced by them
    model.load_state_dict(ema_state, strict=True)
    print(f"EMA load: {len(ema_state)} tensors, "
          f"n_averaged={int(ckpt['ema'].get('n_averaged', -1))}")
    model.eval()

    stats = json.loads((ROOT / dcfg["stats_path"]).read_text(encoding="utf-8"))
    val_full = ForgeSplitDataset(ROOT / dcfg["val_dir"], True, ROOT / dcfg["stats_path"])
    val_ds = Subset(val_full, range(dcfg["val_subset_size"]))
    val_loader = DataLoader(val_ds, batch_size=config["training"]["batch_size"])

    loss_fn = FlowMatchingLoss(config["flow_matching"]["sigma_min"])
    ema_val = _validate(model, loss_fn, val_loader, device)
    print(f"EMA val_loss over {len(val_ds)} samples: {ema_val:.6f}")

    batch = next(iter(DataLoader(Subset(val_full, range(N_SAMPLES)), batch_size=N_SAMPLES)))
    gen = sample(model, batch["sdf"].to(device), batch["scalars"].to(device), FM_STEPS)

    out_dir = ROOT / "outputs/run_01/samples"
    out_dir.mkdir(parents=True, exist_ok=True)
    vm_mean, vm_std = stats["von_mises"]["mean"], stats["von_mises"]["std"]
    print(f"\ngenerated {tuple(gen.shape)} at {FM_STEPS} FM steps "
          f"(normalized space; physical = x*{vm_std:.6e} + {vm_mean:.6e})")
    summary = []
    for i in range(N_SAMPLES):
        a = gen[i, 0].cpu().numpy()
        idx = val_full.paths[i].stem
        np.save(out_dir / f"sample_{i}_{idx}.npy", a)
        ref = batch["x"][i, 0].numpy()
        row = dict(file=f"sample_{i}_{idx}.npy", shape=a.shape,
                   mean=float(a.mean()), std=float(a.std()),
                   min=float(a.min()), max=float(a.max()),
                   ref_mean=float(ref.mean()), ref_std=float(ref.std()),
                   ref_min=float(ref.min()), ref_max=float(ref.max()))
        summary.append(row)
        print(f"  {row['file']}: shape={a.shape} mean={row['mean']:+.4f} "
              f"std={row['std']:.4f} min={row['min']:+.4f} max={row['max']:+.4f}")
        print(f"     ground truth  : mean={row['ref_mean']:+.4f} std={row['ref_std']:.4f} "
              f"min={row['ref_min']:+.4f} max={row['ref_max']:+.4f}")

    (ROOT / "outputs/run_01/eval_summary.json").write_text(
        json.dumps({"ema_val_loss": ema_val, "fm_steps": FM_STEPS,
                    "checkpoint_step": ckpt["step"], "samples": summary}, indent=2),
        encoding="utf-8")
    print("\nwrote outputs/run_01/eval_summary.json")


if __name__ == "__main__":
    main()
